void	tex_1d_bind( INT32 value )
{
	//todoq	this line should be a security
	//todoqq can we load all that first
	value = IMOD( value, BIND_1D_MAX_NB );
	GOL::tex_image_1d( 0, 4, stripeImageWidth, GL_RGBA, GL_UNSIGNED_BYTE, stripeImage + stripeImageWidth * 4 * value );
}

void 	bind_img_1d_init()
{
	tex1d.alloc( BIND_1D_MAX_NB );
	tex_1d_bind( 0 );

	GOL::set_tex_1d_wrap_s( GL_REPEAT );
}
void 	bind_img_1d_deinit()
{
}
